def move_verification_documents(apps, schema_editor):
    Profile = apps.get_model('authentication', 'ProfessionalProfile')
    public_storage = FileSystemStorage(location=settings.MEDIA_ROOT)
    for profile in Profile.objects.all():
        for field_name in ('id_card_front', 'id_card_back'):
            name = getattr(profile, field_name).name
            if not name or not public_storage.exists(name):
                continue
            with public_storage.open(name, 'rb') as source:
                new_name = private_verification_storage.save(name, source)
            public_storage.delete(name)
            profile_field = getattr(profile, field_name)
            profile_field.name = new_name
            profile.save(update_fields=[field_name])


